import{printedArtwork,printedFilm}from'../../modeling/artwork.js';
const title=new URL('./reference-redraw-title.png',import.meta.url).href,controls=new URL('./reference-redraw-controls.png',import.meta.url).href,back=new URL('./reference-redraw-back.png',import.meta.url).href,ports=new URL('./reference-redraw-ports.png',import.meta.url).href;
/** Exact U189 official-photo reference redraws; final PNG only. No firmware screen crop. */
export function addStickers(host){const target=host.parts['TimerPWR complete native assembled shell'],panels=[];for(const o of[{url:title,size:[17.5,2.8],position:[0,17.6,5.3],name:'TimerPWR reference-redrawn title'},{url:controls,size:[17.5,6.3],position:[0,.1,5.3],name:'TimerPWR reference-redrawn key guide'},{url:ports,size:[18,2.65],position:[0,19.82,3.2],face:'top',rotation:Math.PI,name:'TimerPWR reference-redrawn charge/battery port guide'}])panels.push(...(printedArtwork(host,{target,depth:.35,artworkKind:'reference-redraw',...o})??[]));const film=printedFilm(host,{url:back,size:[20.6,21],position:[0,7.75,-5.315],face:'back',name:'TimerPWR reference-redrawn rear adhesive over native inspection recess',artworkKind:'reference-redraw'});if(film)panels.push(film);return panels;}
